import{_ as o,a as s,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 全册短语与句型 · 第24–48课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第二册：实践与进步 · 全册短语与句型 · 第24–48课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-2/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册短语与句型 · 第1–23课","link":"/life/english/new-concept/book-2/phrases-part-01"},"next":{"text":"第二册：实践与进步 · 全册短语与句型 · 第49–74课","link":"/life/english/new-concept/book-2/phrases-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册短语与句型 · 第1–23课","link":"/life/english/new-concept/book-2/phrases-part-01"},"next":{"text":"第二册：实践与进步 · 全册短语与句型 · 第49–74课","link":"/life/english/new-concept/book-2/phrases-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-2/phrases-part-02.md","filePath":"life/english/new-concept/book-2/phrases-part-02.md"}'),l={name:"life/english/new-concept/book-2/phrases-part-02.md"};function i(t,e,r,h,p,c){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第二册-实践与进步-·-全册短语与句型-·-第24–48课" tabindex="-1">第二册：实践与进步 · 全册短语与句型 · 第24–48课 <a class="header-anchor" href="#第二册-实践与进步-·-全册短语与句型-·-第24–48课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册短语与句型 · 第24–48课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="lesson-24-·-情态动词的意义与形式" tabindex="-1">Lesson 24 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-24-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 24 · 情态动词的意义与形式 {#lesson-24-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>look on the bright side — 看积极的一面</li><li>return something to somebody — 把某物归还某人</li></ul><p><strong>句型示范：</strong> I lost my wallet, but someone returned it that evening.</p><p>lost 与 returned 同为过去式推进事件；someone 是未知身份的人，it 指 wallet，but 标记转折。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-024">进入本课</a></p><h2 id="lesson-25-·-间接引语与视角转换" tabindex="-1">Lesson 25 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-25-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 25 · 间接引语与视角转换 {#lesson-25-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>ask somebody a question — 问某人一个问题</li><li>in other words — 换句话说，用于重新解释</li></ul><p><strong>句型示范：</strong> I asked the driver where the bus stopped.</p><p>asked 带听者 the driver 和间接疑问从句；where 引导地点问题，从句不倒装。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-025">进入本课</a></p><h2 id="lesson-26-·-一般现在时与习惯" tabindex="-1">Lesson 26 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-26-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 26 · 一般现在时与习惯 {#lesson-26-·-一般现在时与习惯}&quot;">​</a></h2><ul><li>look at — 看某物，侧重动作</li><li>in my opinion — 在我看来，标记个人观点</li></ul><p><strong>句型示范：</strong> My sister likes paintings with strong colours.</p><p>likes 表稳定偏好，paintings 是泛指复数，with strong colours 为后置修饰语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-026">进入本课</a></p><h2 id="lesson-27-·-过去完成时与先后关系" tabindex="-1">Lesson 27 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-27-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 27 · 过去完成时与先后关系 {#lesson-27-·-过去完成时与先后关系}&quot;">​</a></h2><ul><li>put up a tent — 搭帐篷，代词用 put it up</li><li>wake up — 醒来，过去式为 woke up</li></ul><p><strong>句型示范：</strong> We had covered the bags before the rain started.</p><p>had covered 标记较早动作，before 从句 started 给出过去参照点；bags 是受保护的物品。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-027">进入本课</a></p><h2 id="lesson-28-·-动名词与动词搭配" tabindex="-1">Lesson 28 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-28-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 28 · 动名词与动词搭配 {#lesson-28-·-动名词与动词搭配}&quot;">​</a></h2><ul><li>keep clear — 保持畅通，常见于入口提示</li><li>prevent somebody from doing — 阻止某人做某事</li></ul><p><strong>句型示范：</strong> Parking beside this gate blocks the entrance.</p><p>Parking beside this gate 是动名词短语作主语，整体视为单数，谓语用 blocks。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-028">进入本课</a></p><h2 id="lesson-29-·-现在完成时与过去时间" tabindex="-1">Lesson 29 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-29-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 29 · 现在完成时与过去时间 {#lesson-29-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>take off — 起飞，也可表示脱下，要看语境</li><li>land on — 在某表面着陆</li></ul><p><strong>句型示范：</strong> The small plane has carried a hundred passengers this week.</p><p>has carried 是现在完成时，a hundred passengers 为累计宾语，this week 连接过去活动与现在。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-029">进入本课</a></p><h2 id="lesson-30-·-冠词与可数性" tabindex="-1">Lesson 30 · 冠词与可数性 <a class="header-anchor" href="#lesson-30-·-冠词与可数性" aria-label="Permalink to &quot;Lesson 30 · 冠词与可数性 {#lesson-30-·-冠词与可数性}&quot;">​</a></h2><ul><li>fall into — 掉进，强调进入内部</li><li>on the bank — 在河岸上，此处 bank 不是银行</li></ul><p><strong>句型示范：</strong> A ball landed in the river beside our picnic spot.</p><p>A ball 首次引入对象，the river 是场景内可识别的河流，beside 短语修饰位置。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-030">进入本课</a></p><h2 id="lesson-31-·-一般现在时与习惯" tabindex="-1">Lesson 31 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-31-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 31 · 一般现在时与习惯 {#lesson-31-·-一般现在时与习惯}&quot;">​</a></h2><ul><li>used to do — 过去常做，常暗示如今不同</li><li>save up — 积攒钱，用 for 引出目标</li></ul><p><strong>句型示范：</strong> Mina used to repair bicycles in her parents&#39; garage.</p><p>used to 加原形 repair 表过去习惯，in 后为地点，parents&#39; 是复数所有格。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-031">进入本课</a></p><h2 id="lesson-32-·-被动语态与信息重点" tabindex="-1">Lesson 32 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-32-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 32 · 被动语态与信息重点 {#lesson-32-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>pay for — 为商品付款</li><li>take something back — 把某物退回，代词用 take it back</li></ul><p><strong>句型示范：</strong> The missing receipt has been found behind the counter.</p><p>receipt 是单数承受者，has been found 为完成时被动；behind the counter 说明发现地点。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-032">进入本课</a></p><h2 id="lesson-33-·-过去完成时与先后关系" tabindex="-1">Lesson 33 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-33-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 33 · 过去完成时与先后关系 {#lesson-33-·-过去完成时与先后关系}&quot;">​</a></h2><ul><li>by the time — 到……时候，强调截止参照</li><li>make your way to — 费力或逐步前往某处</li></ul><p><strong>句型示范：</strong> By the time we reached the shore, we had lost our map.</p><p>By the time 从句 reached 建立过去参照点，主句 had lost 回顾更早事件，our map 是宾语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-033">进入本课</a></p><h2 id="lesson-34-·-间接引语与视角转换" tabindex="-1">Lesson 34 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-34-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 34 · 间接引语与视角转换 {#lesson-34-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>at the police station — 在警察局</li><li>a long time ago — 很久以前，通常配过去时</li></ul><p><strong>句型示范：</strong> The police told me that my bicycle had been found.</p><p>told me 引出接收信息的人；had been found 是从通知时刻回看更早找回动作的被动结构。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-034">进入本课</a></p><h2 id="lesson-35-·-不定式与目的" tabindex="-1">Lesson 35 · 不定式与目的 <a class="header-anchor" href="#lesson-35-·-不定式与目的" aria-label="Permalink to &quot;Lesson 35 · 不定式与目的 {#lesson-35-·-不定式与目的}&quot;">​</a></h2><ul><li>run away — 逃跑</li><li>stop somebody from doing — 阻止某人做某事</li></ul><p><strong>句型示范：</strong> A cyclist stopped to help the shop assistant.</p><p>stopped 是主线过去动作，to help 是目的状语，the shop assistant 为 help 的宾语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-035">进入本课</a></p><h2 id="lesson-36-·-将来进行时与过程" tabindex="-1">Lesson 36 · 将来进行时与过程 <a class="header-anchor" href="#lesson-36-·-将来进行时与过程" aria-label="Permalink to &quot;Lesson 36 · 将来进行时与过程 {#lesson-36-·-将来进行时与过程}&quot;">​</a></h2><ul><li>set a record — 创立纪录</li><li>keep an eye on — 留意、照看，不能逐字译成把眼睛放上去</li></ul><p><strong>句型示范：</strong> At noon tomorrow, Ava will be swimming near the eastern coast.</p><p>will be swimming 是将来进行时，At noon tomorrow 给出参照时点，near 表示附近而非已经上岸。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-036">进入本课</a></p><h2 id="lesson-37-·-被动语态与信息重点" tabindex="-1">Lesson 37 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-37-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 37 · 被动语态与信息重点 {#lesson-37-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>take place — 发生、举行，不用被动语态</li><li>be ready for — 为……准备就绪</li></ul><p><strong>句型示范：</strong> The new stadium will be opened in September.</p><p>stadium 是被开放的设施，will be opened 为将来被动，in September 表月份。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-037">进入本课</a></p><h2 id="lesson-38-·-过去完成时与先后关系" tabindex="-1">Lesson 38 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-38-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 38 · 过去完成时与先后关系 {#lesson-38-·-过去完成时与先后关系}&quot;">​</a></h2><ul><li>dream of — 梦想、向往，可接动名词</li><li>except for — 除了某个局部因素，用于说明例外</li></ul><p><strong>句型示范：</strong> Before he moved north, Joel had dreamed of a quiet village.</p><p>Before 从句 moved 给出过去参照，had dreamed 回顾更早的愿望；dream of 后接名词短语。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-038">进入本课</a></p><h2 id="lesson-39-·-间接引语与视角转换" tabindex="-1">Lesson 39 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-39-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 39 · 间接引语与视角转换 {#lesson-39-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>ask about — 询问有关……的情况</li><li>be ready to — 准备好做某事，后接原形</li></ul><p><strong>句型示范：</strong> Evan asked the nurse whether he could leave that afternoon.</p><p>whether 引出是否问题，he could leave 为陈述语序；that afternoon 从转述者的视角定位时间。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-039">进入本课</a></p><h2 id="lesson-40-·-非真实条件句" tabindex="-1">Lesson 40 · 非真实条件句 <a class="header-anchor" href="#lesson-40-·-非真实条件句" aria-label="Permalink to &quot;Lesson 40 · 非真实条件句 {#lesson-40-·-非真实条件句}&quot;">​</a></h2><ul><li>make conversation — 交谈、找话题，通常不用 a</li><li>ask about somebody&#39;s work — 询问某人的工作</li></ul><p><strong>句型示范：</strong> If I knew more about her work, I would ask better questions.</p><p>knew 表非真实现在假设，would ask 表假设结果；better 是 good 的比较级。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-040">进入本课</a></p><h2 id="lesson-41-·-情态动词的意义与形式" tabindex="-1">Lesson 41 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-41-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 41 · 情态动词的意义与形式 {#lesson-41-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>try something on — 试穿试戴，代词用 try it on</li><li>go with — 与……搭配，描述衣着配色</li></ul><p><strong>句型示范：</strong> You need not buy the hat just because it is fashionable.</p><p>need not 在此是情态用法，后接 buy 原形；because 从句说明不应成为唯一理由的因素。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-041">进入本课</a></p><h2 id="lesson-42-·-动词、宾语与补足语" tabindex="-1">Lesson 42 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-42-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 42 · 动词、宾语与补足语 {#lesson-42-·-动词、宾语与补足语}&quot;">​</a></h2><ul><li>move to the rhythm — 随节奏移动</li><li>look as if — 看起来好像，后接从句</li></ul><p><strong>句型示范：</strong> We watched the bird move towards the musician&#39;s hand.</p><p>watched 后接宾语 the bird，再接原形 move 作宾语补足语；towards 标记方向。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-042">进入本课</a></p><h2 id="lesson-43-·-情态动词的意义与形式" tabindex="-1">Lesson 43 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-43-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 43 · 情态动词的意义与形式 {#lesson-43-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>run low on — 某物快用完了</li><li>manage to do — 设法成功做成某事</li></ul><p><strong>句型示范：</strong> The pilot was able to land before the storm arrived.</p><p>was able to land 描述这次成功结果，before 从句限定时间，storm arrived 是之后的事件。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-043">进入本课</a></p><h2 id="lesson-44-·-真实条件句" tabindex="-1">Lesson 44 · 真实条件句 <a class="header-anchor" href="#lesson-44-·-真实条件句" aria-label="Permalink to &quot;Lesson 44 · 真实条件句 {#lesson-44-·-真实条件句}&quot;">​</a></h2><ul><li>keep to the path — 不偏离小路</li><li>out of breath — 气喘吁吁，breath 是名词</li></ul><p><strong>句型示范：</strong> If we keep to the path, we can reach the village before dark.</p><p>if 从句用一般现在时 keep，主句 can reach 表条件下的能力或可能，before dark 为时间界限。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-044">进入本课</a></p><h2 id="lesson-45-·-被动语态与信息重点" tabindex="-1">Lesson 45 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-45-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 45 · 被动语态与信息重点 {#lesson-45-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>pay back — 偿还钱款，代词用 pay it back</li><li>feel guilty about — 因……感到内疚</li></ul><p><strong>句型示范：</strong> The missing money has been returned in a plain envelope.</p><p>money 不可数，助动词用 has；has been returned 是完成时被动，in 表容器。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-045">进入本课</a></p><h2 id="lesson-46-·-数量表达与范围" tabindex="-1">Lesson 46 · 数量表达与范围 <a class="header-anchor" href="#lesson-46-·-数量表达与范围" aria-label="Permalink to &quot;Lesson 46 · 数量表达与范围 {#lesson-46-·-数量表达与范围}&quot;">​</a></h2><ul><li>spend money on — 在……上花钱</li><li>be worth the cost — 值得这个价钱</li></ul><p><strong>句型示范：</strong> The overnight train cost more but offered fewer comfortable seats.</p><p>cost 是过去式，与原形同形；more 省略比较中的 money，fewer 修饰可数复数 seats。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-046">进入本课</a></p><h2 id="lesson-47-·-间接引语与视角转换" tabindex="-1">Lesson 47 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-47-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 47 · 间接引语与视角转换 {#lesson-47-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>be said to — 据说，后接原形</li><li>look into — 调查，不等于向里面看这一字面义</li></ul><p><strong>句型示范：</strong> The cellar was said to be haunted, but no one had evidence.</p><p>was said to be 是被动报道结构；but no one had evidence 限定传闻可信度，不确认鬼魂存在。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-047">进入本课</a></p><h2 id="lesson-48-·-时间、原因与让步从句" tabindex="-1">Lesson 48 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-48-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 48 · 时间、原因与让步从句 {#lesson-48-·-时间、原因与让步从句}&quot;">​</a></h2><ul><li>nod your head — 点头表示回应</li><li>as soon as — 一……就……，突出紧接关系</li></ul><p><strong>句型示范：</strong> As soon as the dentist removed the mirror, I asked a question.</p><p>As soon as 从句给出先发生的动作，主句 asked 紧接其后；两者都是具体过去事件。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-048">进入本课</a></p>',128)])])}const b=o(l,[["render",i]]);export{u as __pageData,b as default};
